create table if not exists public.school_member_invites (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  email text not null check (position('@' in email) > 1),
  base_role text not null check (base_role in ('administrator','secretary','accountant','teacher','supervisor')),
  custom_role_id uuid references public.school_roles(id) on delete set null,
  status text not null default 'pending' check (status in ('pending','accepted','revoked')),
  invited_by uuid references auth.users(id) on delete set null,
  accepted_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  accepted_at timestamptz,
  unique (school_id, email)
);
create index if not exists school_member_invites_school_status_idx on public.school_member_invites(school_id, status);
alter table public.school_member_invites enable row level security;
create policy school_member_invites_leader_manage on public.school_member_invites for all to authenticated using (schooly_private.can_manage_roles(school_id)) with check (schooly_private.can_manage_roles(school_id));

create or replace function schooly_private.claim_school_member_invites() returns trigger language plpgsql security definer set search_path = public, auth as $$
declare invite_record public.school_member_invites;
begin
  for invite_record in select * from public.school_member_invites where lower(email) = lower(new.email) and status = 'pending' loop
    insert into public.school_memberships(school_id, user_id, role) values (invite_record.school_id, new.id, invite_record.base_role) on conflict (school_id, user_id) do update set role = excluded.role;
    if invite_record.custom_role_id is not null then insert into public.school_member_custom_roles(school_id, user_id, role_id, assigned_by) values (invite_record.school_id, new.id, invite_record.custom_role_id, invite_record.invited_by) on conflict do nothing; end if;
    update public.school_member_invites set status = 'accepted', accepted_by = new.id, accepted_at = now() where id = invite_record.id;
  end loop;
  return new;
end;
$$;
drop trigger if exists schooly_claim_member_invites on auth.users;
create trigger schooly_claim_member_invites after insert on auth.users for each row execute procedure schooly_private.claim_school_member_invites();
